def apply_edits(content, edits, label):
    result = content
    for i,e in enumerate(edits,1):
        old,new=e['old'],e['new']
        count=result.count(old)
        if count==1: result=result.replace(old,new,1)
        elif count==0 and new in result: pass
        else: raise ValueError(f"Incompatible source at {label} step {i}: found {count} matching anchors")
    return result

def main():
    here=pathlib.Path(__file__).resolve().parent
    candidates=[pathlib.Path(sys.argv[1]).resolve()] if len(sys.argv)>1 else [here,here/'web',pathlib.Path.cwd(),pathlib.Path.cwd()/'web']
    root=next((p for p in candidates if (p/'src/game/fighter.ts').is_file()),None)
    if root is None:
        print('ERROR: Put the installer inside fight-royale/web, or pass the path to web as its first argument.')
        return 2
    payload=json.loads(zlib.decompress(base64.b85decode(DATA)))
    fighter=(root/'src/game/fighter.ts').read_text(encoding='utf8')
    game=(root/'src/game/game.ts').read_text(encoding='utf8')
    kit=(root/'src/game/kits.ts').read_text(encoding='utf8')
    ai=(root/'src/game/ai.ts').read_text(encoding='utf8')
    hud=(root/'src/ui/GameView.tsx').read_text(encoding='utf8')
    if ('ZENITH_BASIC_DMG_25P_V8' in kit and 'ZENITH_TEMPO_GUARD_STALL_V8' in ai
        and 'ZENITH_VISIBLE_TEMPO_V8' in hud and 'ZENITH_TEMPO_01X_5S_V7' in fighter):
        print('V8 already installed. No files changed.')
        return 0
    is_v7='ZENITH_TEMPO_01X_5S_V7' in fighter and 'ZENITH_TEMPO_01X_5S_V7' in game
    is_v6='ZENITH_HIT_TEMPO_V1' in fighter and 'ZENITH_BLEED_TEMPO_V1' in game
    try:
        edits={}
        if is_v7:
            edits=payload['v8']
            print('Detected V7: applying only V8 refinements.')
        elif is_v6:
            edits={rel:list(steps) for rel,steps in payload['v7']['upgrade'].items()}
            for rel,steps in payload['v8'].items():edits.setdefault(rel,[]).extend(steps)
            print('Detected V6: applying V7 + V8 refinements.')
        else:
            edits={rel:list(steps) for rel,steps in payload['v7']['full'].items()}
            for rel,steps in payload['v7']['upgrade'].items():edits.setdefault(rel,[]).extend(steps)
            for rel,steps in payload['v8'].items():edits.setdefault(rel,[]).extend(steps)
            print('Detected original code: applying complete V6 + V7 + V8 changes.')
        changed={}
        for rel,steps in edits.items():
            p=root/rel
            if not p.is_file():raise FileNotFoundError(f'Missing {rel}')
            before=p.read_text(encoding='utf8')
            after=apply_edits(before,steps,rel)
            if before!=after:changed[p]=(before,after)
        if not changed:
            print('Everything already up to date.')
            return 0
        stamp=datetime.now().strftime('%Y%m%d_%H%M%S_%f')
        backups=[]
        try:
            for path in changed:
                backup=path.with_name(path.name+f'.before_{PATCH}_{stamp}.bak')
                shutil.copy2(path,backup)
                backups.append((path,backup))
            for path,(_,after) in changed.items():
                tmp=path.with_name(path.name+f'.{PATCH}.tmp')
                tmp.write_text(after,encoding='utf8')
                tmp.replace(path)
                print('UPDATED',path.relative_to(root))
        except BaseException:
            for path,backup in backups:shutil.copy2(backup,path)
            raise
    except Exception as exc:
        print('ERROR: Nothing was modified unless safe backups were already created.')
        print(exc)
        return 3
    print('DONE: Zenith +0.01x per hit, expires 5s after last successful hit (14 stacks max).')
    print('Zenith basic L1-L5 damage is now 75% of original; heavy/skills unchanged.')
    print('CPU guard-stalls visible Zenith Tempo, and the opponent HUD shows stacks, speed, time.')
    print('Includes all prior Nythera scythe, Orbit Mark and Zenith Bleed/AI fixes where needed.')
    print('Run npx tsc --noEmit -p .  then npm run dev')
    return 0

if __name__=='__main__':sys.exit(main())
